<?php /** @var array $missing @var array $pages */ ?>
<div class="card"><div class="card-heading"><div><h2>404 insights</h2><p class="muted">Repeated missing URLs often indicate an old link that should redirect to a live page.</p></div><?php if ($missing !== []): ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="clear"><button class="btn small secondary" type="submit">Clear log</button></form><?php endif; ?></div>
<?php if ($missing === []): ?><div class="empty-state">No public 404 paths have been recorded.</div><?php else: ?>
<table><tr><th>Missing path</th><th>Hits</th><th>Last seen</th><th>Create redirect</th></tr>
<?php foreach ($missing as $row): ?><tr><td><code><?= e($row['path']) ?></code><?php if ($row['last_referrer']): ?><br><span class="muted">from <?= e($row['last_referrer']) ?></span><?php endif; ?></td><td><?= (int) $row['hits'] ?></td><td><?= e($row['last_seen']) ?></td><td><form method="post" class="inline-fields"><?= $csrf->field() ?><input type="hidden" name="action" value="redirect"><input type="hidden" name="source" value="<?= e_attr($row['path']) ?>"><select name="target" required><option value="">Choose live page…</option><?php foreach ($pages as $page): ?><option value="/<?= e_attr($page['slug']) ?>"><?= e($page['title']) ?> — /<?= e($page['slug']) ?></option><?php endforeach; ?></select><button class="btn small" type="submit">Redirect</button></form></td></tr><?php endforeach; ?>
</table><?php endif; ?></div>
<div class="card"><h2 style="margin-top:0">Search-engine endpoints</h2><p><a href="<?= e_attr(rtrim($basePath, '/') . '/sitemap.xml') ?>" target="_blank" rel="noopener">Open sitemap.xml ↗</a> · <a href="<?= e_attr(rtrim($basePath, '/') . '/robots.txt') ?>" target="_blank" rel="noopener">Open robots.txt ↗</a></p><p class="muted">The sitemap includes only published, indexable, non-trashed pages. Per-page canonical, description, social image, and noindex controls live in the page editor.</p></div>
